      "key": "navbar-floating",
      "content": {
        "eyebrow": "Navbar",
        "title": "Pause",
        "href": "#features-alternating",
        "items": [
          {
            "title": "A clear starting point",
            "description": "Everything you need, thoughtfully organized."
          },
          {
            "title": "Built around your day",
            "description": "Flexible tools that adapt to the way you work."
          },
          {
            "title": "Room to grow",
            "description": "Start simply. Add more when you need it."
          },
          {
            "title": "People first",
            "description": "Accessible, intuitive experiences for everyone."
          }
        ]
      }
    },
    {
      "id": "hero-product",
      "key": "hero-product",
      "content": {
        "eyebrow": "Pause",
        "title": "A little space in your day.",
        "description": "Simple daily practices to help you slow down, reset, and feel more present.",
