        "title": "Everything you need. Nothing in your way.",
        "href": "#features-alternating",
        "items": [
          {
            "title": "Start with five minutes",
            "description": "Short guided practices that fit between the busy parts of your day."
          },
          {
            "title": "Find your own rhythm",
            "description": "Choose breathing, reflection, or a quiet moment to reset."
          },
          {
            "title": "Notice your progress",
            "description": "A gentle journal helps you see how small habits add up."
          }
        ]
      }
