        "eyebrow": "Testimonials",
        "title": "In good company",
        "href": "#features-alternating",
        "items": [
          {
            "title": "Thoughtful from the first detail.",
            "description": "We found the clarity we had been looking for. The whole experience felt considered and easy. — Jamie Parker, Studio North"
          },
          {
            "title": "A real difference in our day.",
            "description": "Our team spends less time coordinating and more time doing work we care about. — Alex Kim, Forma"
          },
          {
            "title": "Simple in the best way.",
            "description": "It does what we need beautifully, without getting in the way. — Morgan Reed, Fieldwork"
          }
        ]
      }
    },
